-- PROD LOAD: restores wiped reservations/bookings/modules/ranges.
-- Run with: psql -U contact -d contact_system -v ON_ERROR_STOP=1 -f ship_to_prod.sql
-- Guards abort unless targets are empty (never run twice / on live data).

BEGIN;

DO $$ BEGIN
  IF (SELECT count(*) FROM public.reservations) > 0 THEN
    RAISE EXCEPTION 'refusing: reservations not empty';
  END IF;
  IF (SELECT count(*) FROM public.reservation_bookings) > 0 THEN
    RAISE EXCEPTION 'refusing: reservation_bookings not empty';
  END IF;
  IF (SELECT count(*) FROM public.project_modules) > 0 THEN
    RAISE EXCEPTION 'refusing: project_modules not empty';
  END IF;
  IF (SELECT count(*) FROM public.reservation_disabled_ranges) > 0 THEN
    RAISE EXCEPTION 'refusing: reservation_disabled_ranges not empty';
  END IF;
END $$;

