SELECT setval(pg_get_serial_sequence('public.reservations','id'), (SELECT max(id) FROM public.reservations));
SELECT setval(pg_get_serial_sequence('public.project_modules','id'), (SELECT max(id) FROM public.project_modules));
SELECT setval(pg_get_serial_sequence('public.reservation_bookings','id'), (SELECT max(id) FROM public.reservation_bookings));
SELECT setval(pg_get_serial_sequence('public.reservation_disabled_ranges','id'), (SELECT max(id) FROM public.reservation_disabled_ranges));

SELECT 'prod_reservations' AS metric, count(*)::text AS value FROM public.reservations
UNION ALL SELECT 'prod_bookings', count(*)::text AS value FROM public.reservation_bookings
UNION ALL SELECT 'prod_modules', count(*)::text AS value FROM public.project_modules
UNION ALL SELECT 'prod_ranges', count(*)::text AS value FROM public.reservation_disabled_ranges
UNION ALL SELECT 'prod_range_links', count(*)::text AS value FROM public.reservation_disabled_range_services;

